# generated by scenegen.py: renders one act of the documentary
"""Renders one act. Choose it with CINEMATIC_ACT (default 1):

  CINEMATIC_ACT=2 python3 render.py --project . --probe 120,135

Each act is its own board; 06_film/acts.json gives each act's time range for --t0 and --t1.
"""
import importlib.util
import os
import pathlib

ACTS = {
    1: '06_film/act_01/scene.py',
}


def build_film(doc):
    n = int(os.environ.get("CINEMATIC_ACT", "1"))
    if n not in ACTS:
        raise SystemExit(f"CINEMATIC_ACT={n}: this film has acts {sorted(ACTS)}")
    path = pathlib.Path(__file__).resolve().parent / ACTS[n]
    spec = importlib.util.spec_from_file_location(f"act_{n}", path)
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod.build_film(doc)
